/**
 * One live connection the double has been asked for.
 *
 * A test drives frames through {@link FakeWatch.send} and ends it with
 * {@link FakeWatch.close}, which is what lets the assertions about ordering, deduplication
 * and reconnect run with no server, no SSE and no timing.
 */
export interface FakeWatch {
  readonly targetId: string;
  /** What the app asked to resume after, or `undefined` for "the server picks". */
  readonly cursor: number | undefined;
  /** Delivers one frame, unless the app has stopped this watch. */
  readonly send: (frame: LiveFrame) => void;
  /**
   * Ends it, the way the client would.
   *
   * Takes the typed {@link LiveClosed} rather than a sentence, so a test can say "the
   * session expired" as the client actually says it. That distinction is the one the app
   * must act on — see `LiveClosed` — and a double that only offered a string could not
   * express it.
   */
  readonly close: (closed: LiveClosed) => void;
  /** Whether the app called the returned stop function. */
  readonly stopped: () => boolean;
}

/* ── The double ──────────────────────────────────────────────────────────────── */

/** One call that was made, for the tests that care that it was made at all. */
export interface RecordedCall {
  readonly method: keyof ServerClient;
  readonly args: readonly unknown[];
}

/**
 * The double itself.
 *
 * `implements ServerClient` is the point of the class: it is checked against the real
 * client's type, so an endpoint that gains a parameter or changes its success shape
 * breaks this file at compile time rather than leaving a green test suite describing a
 * server that no longer exists.
 */
export class FakeServer implements ServerClient {
  /** Every call that reached this client, in order. */
  readonly calls: RecordedCall[] = [];

  /** What `setToken` was last handed. `undefined` after a sign-out. */
  token: string | undefined;

  /** What a reload would find. Set this to test {@link App.restore}. */
  stored: string | undefined;

  /** Methods whose answers are being held open, to the gate holding each. */
  private readonly held = new Map<keyof ServerClient, Promise<void>>();

  /**
   * Holds this method's answers open until the returned function is called.
   *
   * A real round trip takes long enough for the operator to click something else, and
   * several of the things worth asserting are only true *during* that window — what the
   * screen does when a run that was started on one target finishes starting after the
   * operator has opened another. Without this a test can only observe the two endpoints
   * and has to take the middle on faith.
   *
   * One method at a time, deliberately: a test that froze every call could not navigate
   * while one was in flight, which is the whole manoeuvre.
   */
  hold(method: keyof ServerClient): () => void {
    let open = (): void => {};
    this.held.set(
      method,
      new Promise<void>((resolve) => {
        open = () => {
          this.held.delete(method);
          resolve();
        };
      }),
    );
    return () => {
      open();
    };
  }

  /* Each slot is pre-set to a bland success; a test replaces the ones it is about. */

  onOpenSession: (baseUrl: string, password: string) => Answer<"openSession"> =
    () => ok(sessionOpened());

  onProbe: (baseUrl: string) => Answer<"probe"> = () => ok(sessionProbe());

  onTargets: (baseUrl: string) => Answer<"targets"> = () => ok([]);

  onTarget: (baseUrl: string, targetId: string) => Answer<"target"> = (
    _baseUrl,
    targetId,
  ) => ok(targetView(targetSummary({ id: targetId, name: targetId })));

  onFolders: (baseUrl: string, path?: string) => Answer<"folders"> = () =>
    ok(folderListing());

  onCreateTarget: (
    ...args: Parameters<ServerClient["createTarget"]>
  ) => Answer<"createTarget"> = (_baseUrl, draft) =>
    ok(
      targetSummary({
        id: draft.name,
        name: draft.name,
        workspacePath: draft.workspacePath,
        scopeNote: draft.scopeNote,
      }),
    );

  onStartRun: (
    ...args: Parameters<ServerClient["startRun"]>
  ) => Answer<"startRun"> = (_baseUrl, targetId) =>
    ok(runStarted({ targetId }));

  onStopRun: (
    baseUrl: string,
    targetId: string,
    attemptId: string,
  ) => Answer<"stopRun"> = (_baseUrl, targetId, attemptId) =>
    ok(runStopped({ targetId, attemptId }));

  onGoals: (baseUrl: string, targetId: string) => Answer<"goals"> = () =>
    ok({ goals: [] });

  onCreateGoal: (
    ...args: Parameters<ServerClient["createGoal"]>
  ) => Answer<"createGoal"> = (_baseUrl, targetId, draft) =>
    ok(
      goalView({
        targetId,
        name: draft.name ?? "",
        description: draft.description,
      }),
    );

  onGoal: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"goal"> = (_baseUrl, targetId, goalId) =>
    ok(goalView({ targetId, goalId }));

  onIntents: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"intents"> = () => ok({ intents: [] });

  onGoalObservations: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"goalObservations"> = () => ok({ observations: [] });

  onGoalBriefing: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"goalBriefing"> = (_baseUrl, targetId, goalId) =>
    ok(goalBriefingView({ targetId, goalId }));

  onPlan: (...args: Parameters<ServerClient["plan"]>) => Answer<"plan"> = (
    _baseUrl,
    targetId,
    goalId,
  ) => ok(planRoundStarted({ targetId, goalId }));

  /**
   * No rounds by default, which is what a goal nobody has planned yet really has.
   *
   * The alternative — a plausible settled round — would make every test that does not care
   * about planning render a disposition, and a test asserting the empty state would have to
   * override it to get there.
   */
  onGoalRounds: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"goalRounds"> = () => ok({ rounds: [] });

  /** Nothing in flight by default, for the reason `onRuns` answers with nothing. */
  onRounds: (baseUrl: string) => Answer<"rounds"> = () => ok([]);

  /**
   * No replayed narration by default, matching `onGoalRounds`'s empty goal.
   *
   * A goal with no rounds has no narration, so the pair is consistent without a test
   * having to override both to get the ordinary empty state.
   */
  onGoalNarration: (
    baseUrl: string,
    targetId: string,
    goalId: string,
  ) => Answer<"goalNarration"> = (_baseUrl, targetId, goalId) =>
    ok(goalNarrationView({ targetId, goalId }));

  /** A stop that worked, answering with the round as `interrupted`. */
  onStopRound: (
    ...args: Parameters<ServerClient["stopRound"]>
  ) => Answer<"stopRound"> = (_baseUrl, targetId, goalId, roundId) =>
    ok(
      planRoundView({
        targetId,
        goalId,
        roundId,
        status: "interrupted",
        disposition: null,
        dispositionRationale: null,
        endedAt: AT + 2_000,
      }),
    );

  onCreateIntent: (
    ...args: Parameters<ServerClient["createIntent"]>
  ) => Answer<"createIntent"> = (_baseUrl, _targetId, goalId, draft) =>
    ok(intentView({ goalId, question: draft.question }));

  onAbandonIntent: (
    ...args: Parameters<ServerClient["abandonIntent"]>
  ) => Answer<"abandonIntent"> = (_baseUrl, _targetId, intentId) =>
    ok(intentView({ intentId, status: "abandoned" }));

  onEndGoal: (
    ...args: Parameters<ServerClient["endGoal"]>
  ) => Answer<"endGoal"> = (_baseUrl, targetId, goalId, draft) =>
    ok(
      goalView({
        targetId,
        goalId,
        status: draft.status,
        endedAt: AT + 1,
        endedBy: "operator",
        endReason: draft.reason,
      }),
    );

  onHarnesses: (baseUrl: string) => Answer<"harnesses"> = () => ok([]);

  onTranscript: (
    baseUrl: string,
    targetId: string,
    attemptId: string,
  ) => Answer<"transcript"> = (_baseUrl, targetId, attemptId) =>
    ok(attemptTranscript({ targetId, attemptId }));

  onRuns: (baseUrl: string) => Answer<"runs"> = () => ok([]);

  /** Every live connection asked for, oldest first. See {@link FakeWatch}. */
  readonly watches: FakeWatch[] = [];

  /* The {@link ServerClient} surface. Each one logs, then defers to its slot. */

  storedToken = (): string | undefined => {
    this.calls.push({ method: "storedToken", args: [] });
    return this.stored;
  };

  setToken = (token: string | undefined): void => {
    this.calls.push({ method: "setToken", args: [token] });
    this.token = token;
  };

  openSession = (baseUrl: string, password: string) =>
    this.record("openSession", [baseUrl, password], () =>
      this.onOpenSession(baseUrl, password),
    );

  probe = (baseUrl: string) =>
    this.record("probe", [baseUrl], () => this.onProbe(baseUrl));

  targets = (baseUrl: string) =>
    this.record("targets", [baseUrl], () => this.onTargets(baseUrl));

  target = (baseUrl: string, targetId: string) =>
    this.record("target", [baseUrl, targetId], () =>
      this.onTarget(baseUrl, targetId),
    );

  folders = (baseUrl: string, path?: string) =>
    this.record("folders", [baseUrl, path], () =>
      this.onFolders(baseUrl, path),
    );

  createTarget = (...args: Parameters<ServerClient["createTarget"]>) =>
    this.record("createTarget", args, () => this.onCreateTarget(...args));

  startRun = (...args: Parameters<ServerClient["startRun"]>) =>
    this.record("startRun", args, () => this.onStartRun(...args));

  stopRun = (baseUrl: string, targetId: string, attemptId: string) =>
    this.record("stopRun", [baseUrl, targetId, attemptId], () =>
      this.onStopRun(baseUrl, targetId, attemptId),
    );

  goals = (baseUrl: string, targetId: string) =>
    this.record("goals", [baseUrl, targetId], () =>
      this.onGoals(baseUrl, targetId),
    );

  createGoal = (...args: Parameters<ServerClient["createGoal"]>) =>
    this.record("createGoal", args, () => this.onCreateGoal(...args));

  goal = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("goal", [baseUrl, targetId, goalId], () =>
      this.onGoal(baseUrl, targetId, goalId),
    );

  endGoal = (...args: Parameters<ServerClient["endGoal"]>) =>
    this.record("endGoal", args, () => this.onEndGoal(...args));

  intents = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("intents", [baseUrl, targetId, goalId], () =>
      this.onIntents(baseUrl, targetId, goalId),
    );

  goalObservations = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("goalObservations", [baseUrl, targetId, goalId], () =>
      this.onGoalObservations(baseUrl, targetId, goalId),
    );

  goalBriefing = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("goalBriefing", [baseUrl, targetId, goalId], () =>
      this.onGoalBriefing(baseUrl, targetId, goalId),
    );

  plan = (...args: Parameters<ServerClient["plan"]>) =>
    this.record("plan", args, () => this.onPlan(...args));

  goalRounds = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("goalRounds", [baseUrl, targetId, goalId], () =>
      this.onGoalRounds(baseUrl, targetId, goalId),
    );

  rounds = (baseUrl: string) =>
    this.record("rounds", [baseUrl], () => this.onRounds(baseUrl));

  goalNarration = (baseUrl: string, targetId: string, goalId: string) =>
    this.record("goalNarration", [baseUrl, targetId, goalId], () =>
      this.onGoalNarration(baseUrl, targetId, goalId),
    );

  stopRound = (...args: Parameters<ServerClient["stopRound"]>) =>
    this.record("stopRound", args, () => this.onStopRound(...args));

  createIntent = (...args: Parameters<ServerClient["createIntent"]>) =>
    this.record("createIntent", args, () => this.onCreateIntent(...args));

  abandonIntent = (...args: Parameters<ServerClient["abandonIntent"]>) =>
    this.record("abandonIntent", args, () => this.onAbandonIntent(...args));

  harnesses = (baseUrl: string) =>
    this.record("harnesses", [baseUrl], () => this.onHarnesses(baseUrl));

  transcript = (baseUrl: string, targetId: string, attemptId: string) =>
    this.record("transcript", [baseUrl, targetId, attemptId], () =>
      this.onTranscript(baseUrl, targetId, attemptId),
    );

  runs = (baseUrl: string) =>
    this.record("runs", [baseUrl], () => this.onRuns(baseUrl));

  /**
   * Records the connection and hands back its stop function, delivering nothing by itself.
   *
   * Nothing arrives until a test sends it, which is the opposite of the other slots here
   * and is deliberate: a stream that pushed a plausible opening frame on its own would
   * decide what "the beginning of a transcript" looks like, and that is the thing the
   * tests are checking.
   */
  watchLive: ServerClient["watchLive"] = (baseUrl, targetId, options) => {
    this.calls.push({
      method: "watchLive",
      args: [baseUrl, targetId, options.cursor],
    });
    let stopped = false;
    let closed = false;
    this.watches.push({
      targetId,
      cursor: options.cursor,
      send: (frame) => {
        if (!stopped && !closed) options.onFrame(frame);
      },
      close: (ended) => {
        if (stopped || closed) return;
        closed = true;
        options.onClosed(ended);
      },
      stopped: () => stopped,
    });
    return () => {
      stopped = true;
    };
  };

  /** The most recent live connection, for a test that opened exactly one. */
  get watch(): FakeWatch {
    const latest = this.watches[this.watches.length - 1];
    if (latest === undefined) {
      throw new Error("no live transcript connection has been opened");
    }
    return latest;
  }

  /** How many times one method was called. */
  countOf(method: keyof ServerClient): number {
    return this.calls.filter((call) => call.method === method).length;
  }

  /**
   * Logs a call and answers it.
   *
   * The answer is produced *inside* the returned promise rather than before it, so a
   * slot that reads mutable state — `onRuns` answering differently once a stop has
   * happened — sees that state as of when the call is awaited.
   */
  private record<A>(
    method: keyof ServerClient,
    args: readonly unknown[],
    answer: () => A,
  ): Promise<A> {
    this.calls.push({ method, args });
    return (this.held.get(method) ?? Promise.resolve()).then(answer);
  }
}
